changeSet.sql:
UPDATE condition_operands
SET operand_type = 'ATTRIBUTE'
WHERE operand_data_type LIKE 'ATTRIBUTE_%';

UPDATE condition_operands
SET operand_data_type = SUBSTRING(operand_data_type, 11)
WHERE operand_data_type LIKE 'ATTRIBUTE_%';

UPDATE condition_operands
SET operand_type = 'LITERAL'
WHERE operand_type IS NULL OR operand_type = '';
